import { useState } from "react";
import Nav from "./components/Nav/Nav";
import Body from "./components/Body/Body";

import "./App.css";

function App() {
  const [inputData, setInputData] = useState([]);

  const drawInput = (e) => {
    e.preventDefault();
    const formData = e.target;
    const { name, sname, login, password } = formData;
    const data = {
      id: new Date().getTime(),
      name: name.value,
      sname: sname.value,
      login: login.value,
      password: password.value,
      done: false,
      seen: false,
    };
    setInputData([...inputData, data]);
    formData.reset();
  };

  const doneBox = (id) => {
  const [check, setCheck] = useState(false);

    const checkedArray = inputData.map((elm) => {
      if (elm.id === id) {
        elm.done = !check;
        console.log(elm.done);
      }
      return elm;
    });
    // setCheck(checkedArray);
    setInputData(checkedArray);
    console.log(inputData);
  };

  const deleteBox = (id) => {
    const deletedItem = inputData.filter((elm) => elm.id !== id);
    setInputData(deletedItem);
  };

  return (
    <div>
      <Nav drawInput={drawInput} />
      <Body inputData={inputData} deleteBox={deleteBox} doneBox={doneBox} />
    </div>
  );
}

export default App;
